class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        hashList = {}
        for i, j in enumerate(nums):
            hashList[j] = i
        
        for i, j in enumerate(nums):
            difference = target - j
            if difference in hashList and hashList[difference]!= i:
                index = hashList[difference]
                return [i, index]
        return []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           

